head.script:
scwin.init = function() {
    window.listElemStr = "";
    listElemStr += "<w2:list xmlns:w2=\"http://www.inswave.com/websquare\" tagName='ul' style='' class='w2grid_contextMenu'>";
    listElemStr += "	<w2:listRow tagName='li' style='height: 20px; display:block; border-top: 0px; border-left:0px; border-right:0px;' class='w2grid_contextMenu_row'>";
    listElemStr += "		<w2:listColumn id='col1' inputType='text' style='padding-left: 10px' class='w2grid_contextMenu_column' />";
    listElemStr += "	</w2:listRow>";
    listElemStr += "</w2:list>";
    window.jsonData = [{
        "col1": "자식노드로 추가"
    }, {
        "col1": "형제노드로 추가"
    }];
    window.listElem = WebSquare.xml.parse(listElemStr, true);
    window.listXML = listElem.documentElement;
    window.contextMenu = new WebSquare.uiplugin.list("treeView_contextMenu_list", "", listXML);
    contextMenu.writeTo(WebSquare.getBody());
    contextMenu.setJSON(jsonData);
    contextMenu.hide();
    contextMenu.setSize(180, 40);
    contextMenu.activate();
    scwin.setContextMenuAction();
}
scwin.setContextMenuAction = function() {
    contextMenu.event.addListener(contextMenu.render, "onclick", function(e) {
        WebSquare.event.stopPropagation(e);
        var it = window.contextMenu.event.getTargetIterator(e, this.render);
        var targetRow;
        while (it.next()) {
            if (it.match("w2grid_contextMenu_column")) {
                targetRow = it.getElement().parentNode;
                break;
            }
            if (it.match("w2grid_contextMenu_row")) {
                targetRow = it.getElement();
                break;
            }
            if (it.match("w2grid_contextMenu")) {
                break;
            }
        }
        if (targetRow.innerText == '형제노드로 추가') {
            treeview.moveNode(dragInfo.dragNode.index, dragInfo.dropNode.index, false);
        } else if (targetRow.innerText == '자식노드로 추가') {
            treeview.moveNode(dragInfo.dragNode.index, dragInfo.dropNode.index, true);
        }
        window.contextMenu.hide();
    });
}
scwin.treeview_ondrop = function(dragNode, dropNode, dragControl, dropControl, e) {
    contextMenu.show();
    contextMenu.setPosition(WebSquare.event.getMouseX(e), WebSquare.event.getMouseY(e));
    dragInfo = {
        dragNode: dragNode,
        dropNode: dropNode,
        dragControl: dragControl,
        event: e
    };
};
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate1 = function() {
    scwin.simulateWrapper('#treeview_label_2', 'drag-n-drop', {
        dx: 10,
        dy: 70
    });
}
scwin.setSimulate2 = function() {
    scwin.simulateWrapper('#treeview_label_6', 'drag-n-drop', {
        dx: 10,
        dy: 20
    });
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2grid_contextMenu_column')[0].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#treeview_node_6').text() == '1-1'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 3. '1' 노드하위에 '1-1' 을 Drag 해서 '2' 에 Drop 후 '자식노드로 추가' 메뉴를 클릭한다
    //3. Drag '1-1' to the '1' node and drop it to '2' and click the 'Add as child node' menu.
    //Verify step 3. '1-1' is moved under the '2' node.
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate2()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2grid_contextMenu_column')[0].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#treeview_label_7').text() == '1-1'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

scwin.onpageload = function() {
    window.contextMenu = null;
    window.dragInfo = {};
    scwin.init();
}
